#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define MAX_HEADERS 64
#define BUFFER_SIZE 8192
#define AES_KEY_SIZE 32
#define AES_IV_SIZE 16

typedef struct {
    char name[256];
    char value[1024];
} http_header_t;

typedef struct {
    char method[16];
    char path[512];
    http_header_t headers[MAX_HEADERS];
    int header_count;
    size_t content_length;
    size_t transfer_encoding_chunked;
    char *body;
    size_t body_len;
} http_request_t;

static unsigned char storage_key[AES_KEY_SIZE];
static int key_initialized = 0;

int init_storage_key(void) {
    if (!key_initialized) {
        if (RAND_bytes(storage_key, AES_KEY_SIZE) != 1) {
            /* RNG failure: do not mark as initialized */
            return -1;
        }
        key_initialized = 1;
    }
    return 0;
}

int encrypt_and_store(const char *filename, const unsigned char *data, size_t len) {
    unsigned char iv[AES_IV_SIZE];
    if (RAND_bytes(iv, AES_IV_SIZE) != 1) {
        return -1;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, storage_key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    unsigned char *ciphertext = malloc(len + EVP_MAX_BLOCK_LENGTH + 16);
    if (!ciphertext) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int outlen = 0, tmplen = 0;

    if (EVP_EncryptUpdate(ctx, ciphertext, &outlen, data, (int)len) != 1) {
        free(ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    if (EVP_EncryptFinal_ex(ctx, ciphertext + outlen, &tmplen) != 1) {
        free(ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    outlen += tmplen;

    unsigned char tag[16];
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag) != 1) {
        free(ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    EVP_CIPHER_CTX_free(ctx);

    char safe_path[768];
    snprintf(safe_path, sizeof(safe_path), "/var/encrypted_store/%s.enc", filename);

    FILE *f = fopen(safe_path, "wb");
    if (!f) { free(ciphertext); return -1; }
    fwrite(iv, 1, AES_IV_SIZE, f);
    fwrite(tag, 1, 16, f);
    fwrite(ciphertext, 1, outlen, f);
    fclose(f);
    free(ciphertext);
    return 0;
}

size_t determine_body_length(http_request_t *req) {
    /* RFC 7230 Section 3.3.3: Message Body Length determination
     * Priority: Transfer-Encoding > Content-Length
     * If both present, reject the request (ambiguous) */

    int has_te = req->transfer_encoding_chunked;
    int has_cl = (req->content_length > 0);

    if (has_te && has_cl) {
        /* RFC 7230: A server MUST reject a request with both
         * Transfer-Encoding and Content-Length to prevent smuggling */
        return (size_t)-1; /* Signal error - reject request */
    }

    if (has_te) {
        /* Verify it's actually chunked encoding */
        for (int i = 0; i < req->header_count; i++) {
            if (strcasecmp(req->headers[i].name, "Transfer-Encoding") == 0) {
                char *val = req->headers[i].value;
                while (*val == ' ' || *val == '\t') val++;
                if (strcasecmp(val, "chunked") == 0) {
                    return 0; /* Signal chunked processing */
                }
                /* Non-chunked TE not supported, reject */
                return (size_t)-1;
            }
        }
    }

    if (has_cl) return req->content_length;
    return 0;
}

int parse_headers(const char *raw, size_t raw_len, http_request_t *req) {
    memset(req, 0, sizeof(http_request_t));

    const char *line = raw;
    const char *end = raw + raw_len;

    /* Parse request line */
    sscanf(line, "%15s %511s", req->method, req->path);
    line = strstr(line, "\r\n");
    if (!line) return -1;
    line += 2;

    /* Parse headers */
    while (line < end && *line != '\r') {
        const char *colon = strchr(line, ':');
        if (!colon || req->header_count >= MAX_HEADERS) break;

        size_t name_len = colon - line;
        if (name_len >= 256) break;

        strncpy(req->headers[req->header_count].name, line, name_len);
        req->headers[req->header_count].name[name_len] = '\0';

        const char *val_start = colon + 1;
        while (*val_start == ' ' || *val_start == '\t') val_start++;

        const char *line_end = strstr(val_start, "\r\n");
        if (!line_end) break;

        size_t val_len = line_end - val_start;
        if (val_len >= 1024) val_len = 1023;

        strncpy(req->headers[req->header_count].value, val_start, val_len);
        req->headers[req->header_count].value[val_len] = '\0';

        /* Track special headers */
        if (strcasecmp(req->headers[req->header_count].name, "Content-Length") == 0) {
            req->content_length = (size_t)atol(req->headers[req->header_count].value);
        }
        if (strcasecmp(req->headers[req->header_count].name, "Transfer-Encoding") == 0) {
            req->transfer_encoding_chunked = 1;
        }

        req->header_count++;
        line = line_end + 2;
    }
    return 0;
}

void handle_upload(int client_fd, http_request_t *req, const char *remaining, size_t remaining_len) {
    size_t body_len = determine_body_length(req);

    if (body_len == (size_t)-1) {
        /* Ambiguous request - reject to prevent smuggling */
        const char *resp = "HTTP/1.1 400 Bad Request\r\nContent-Length: 18\r\nConnection: close\r\n\r\nAmbiguous encoding";
        write(client_fd, resp, strlen(resp));
        return;
    }

    if (body_len > 0 && body_len <= BUFFER_SIZE) {
        char *body = malloc(body_len);
        if (!body) {
            const char *resp = "HTTP/1.1 500 Internal Server Error\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
            write(client_fd, resp, strlen(resp));
            return;
        }
        size_t copied = 0;

        if (remaining_len > 0) {
            size_t to_copy = (remaining_len < body_len) ? remaining_len : body_len;
            memcpy(body, remaining, to_copy);
            copied = to_copy;
        }

        while (copied < body_len) {
            ssize_t n = read(client_fd, body + copied, body_len - copied);
            if (n <= 0) break;
            copied += n;
        }

        /* Extract filename from path - sanitize */
        const char *fname = strrchr(req->path, '/');
        fname = fname ? fname + 1 : req->path;

        /* Validate filename: alphanumeric, dots, hyphens only */
        for (const char *p = fname; *p; p++) {
            if (!(*p >= 'a' && *p <= 'z') && !(*p >= 'A' && *p <= 'Z') &&
                !(*p >= '0' && *p <= '9') && *p != '.' && *p != '-' && *p != '_') {
                const char *resp = "HTTP/1.1 400 Bad Request\r\nContent-Length: 16\r\nConnection: close\r\n\r\nInvalid filename";
                write(client_fd, resp, strlen(resp));
                free(body);
                return;
            }
        }

        if (init_storage_key() != 0) {
            const char *resp = "HTTP/1.1 500 Internal Server Error\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
            write(client_fd, resp, strlen(resp));
            free(body);
            return;
        }

        if (encrypt_and_store(fname, (unsigned char *)body, copied) != 0) {
            const char *resp = "HTTP/1.1 500 Internal Server Error\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
            write(client_fd, resp, strlen(resp));
            free(body);
            return;
        }

        const char *resp = "HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: close\r\n\r\nOK";
        write(client_fd, resp, strlen(resp));
        free(body);
    } else {
        const char *resp = "HTTP/1.1 400 Bad Request\r\nContent-Length: 5\r\nConnection: close\r\n\r\nError";
        write(client_fd, resp, strlen(resp));
    }
}

void handle_connection(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t total = 0;

    /* Read until we have complete headers */
    while (total < BUFFER_SIZE - 1) {
        ssize_t n = read(client_fd, buffer + total, BUFFER_SIZE - 1 - total);
        if (n <= 0) break;
        total += n;
        buffer[total] = '\0';
        if (strstr(buffer, "\r\n\r\n")) break;
    }

    char *header_end = strstr(buffer, "\r\n\r\n");
    if (!header_end) { close(client_fd); return; }

    size_t header_len = header_end - buffer + 4;

    http_request_t req;
    parse_headers(buffer, header_len, &req);

    const char *body_start = header_end + 4;
    size_t remaining = total - header_len;

    if (strcmp(req.method, "POST") == 0) {
        handle_upload(client_fd, &req, body_start, remaining);
    } else {
        const char *resp = "HTTP/1.1 405 Method Not Allowed\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
        write(client_fd, resp, strlen(resp));
    }

    close(client_fd);
}

int main(int argc, char *argv[]) {
    int port = 8443;
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    bind(server_fd, (struct sockaddr *)&addr, sizeof(addr));
    listen(server_fd, 128);

    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd >= 0) {
            handle_connection(client_fd);
        }
    }
    return 0;
}
